<template><main class="site-main play-page"><div class="page-shell"><div class="play-layout"><section class="player-column"><div class="player-card"><div class="player-topbar"><div class="player-status"><span></span>正在播放</div><div class="player-format">HD · HLS · 10秒快进</div></div><div class="player-wrap"><video ref="video" controls class="player" playsinline preload="metadata"></video><div v-if="playerLoading" class="player-loading"><i class="bi bi-play-circle"></i><span>{{message}}</span></div></div></div><section class="video-info-card"><div class="info-header"><div><div class="eyebrow">NOW PLAYING</div><h1 class="video-title">{{vod?.vod_name||'正在加载…'}}</h1></div><button class="share-btn" @click="share">分享</button></div><div class="video-meta"><span>高清在线播放</span><span v-if="vod?.vod_hits">{{vod.vod_hits}} 次播放</span><span v-if="vod?.type_name">{{vod.type_name}}</span><span v-if="resumeText">{{resumeText}}</span></div><div v-if="vod?.vod_content" class="description"><b>视频简介</b><div class="description-text">{{vod.vod_content}}</div></div></section></section><aside class="side-panel"><div class="side-card"><div class="side-heading"><div><span class="side-kicker">EXPLORE</span><h2>相关推荐</h2></div></div><div v-if="recommend.length" class="side-list"><router-link v-for="item in recommend.slice(0,6)" :key="item.vod_id" :to="`/play/${item.vod_id}`" class="side-item"><img :src="item.vod_pic" :alt="item.vod_name"><div><strong>{{item.vod_name}}</strong><small>{{item.vod_hits||0}} 次播放</small></div></router-link></div><div v-else class="side-empty">暂无相关推荐</div></div></aside></div><section v-if="recommend.length" class="recommend-section"><div class="section-bar"><div><div class="section-kicker">MORE FOR YOU</div><h2 class="section-heading">猜你喜欢</h2></div></div><div class="video-grid"><VideoCard v-for="item in recommend" :key="item.vod_id" :item="item"/></div></section></div></main></template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue'
import {useRoute} from 'vue-router'
import Plyr from 'plyr'
import 'plyr/dist/plyr.css'
import Hls from 'hls.js'
import {getDetail,getCategoryLatest} from '../api/cms'
import VideoCard from '../components/VideoCard.vue'
const route=useRoute(),video=ref(null),vod=ref(null),recommend=ref([]),playerLoading=ref(true),message=ref('正在加载视频…'),resumeText=ref('')
let player=null,hls=null,timer=null
const HISTORY='cavxx_watch_history',PROGRESS='cavxx_watch_progress'
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key)||JSON.stringify(fallback))}catch{return fallback}}
function history(item){if(!item?.vod_id)return;const a=read(HISTORY,[]).filter(x=>String(x.vod_id)!==String(item.vod_id));a.unshift({vod_id:item.vod_id,vod_name:item.vod_name,vod_pic:item.vod_pic,type_name:item.type_name,watched_at:Date.now()});localStorage.setItem(HISTORY,JSON.stringify(a.slice(0,30)))}
function save(){if(!vod.value?.vod_id||!video.value?.duration||!video.value.currentTime)return;const d=read(PROGRESS,{});d[vod.value.vod_id]={currentTime:video.value.currentTime,duration:video.value.duration};localStorage.setItem(PROGRESS,JSON.stringify(d))}
function destroy(){save();clearInterval(timer);timer=null;hls?.destroy();hls=null;player?.destroy();player=null;if(video.value){video.value.removeAttribute('src');video.value.load()}}
function resume(){const p=read(PROGRESS,{})[vod.value?.vod_id];if(!p||p.currentTime<15||p.currentTime>p.duration-5)return;const apply=()=>{video.value.currentTime=p.currentTime;video.value?.removeEventListener('loadedmetadata',apply)};video.value?.addEventListener('loadedmetadata',apply);resumeText.value='上次看到 '+Math.floor(p.currentTime/60)+':'+String(Math.floor(p.currentTime%60)).padStart(2,'0')}
function init(url){if(!video.value||!url){playerLoading.value=false;message.value='暂无可播放源';return}destroy();playerLoading.value=true;message.value='正在连接播放源…';player=new Plyr(video.value,{controls:['play','progress','current-time','mute','volume','settings','fullscreen'],settings:['quality','speed'],seekTime:10});const ready=()=>{playerLoading.value=false;resume()};video.value.addEventListener('loadedmetadata',ready,{once:true});video.value.addEventListener('error',()=>{playerLoading.value=true;message.value='播放失败，请重试'});video.value.addEventListener('timeupdate',()=>{if(video.value.currentTime>5)history(vod.value)});if(Hls.isSupported()){hls=new Hls({enableWorker:true,backBufferLength:90});hls.on(Hls.Events.MANIFEST_PARSED,ready);hls.on(Hls.Events.ERROR,(_,d)=>{if(d?.fatal){playerLoading.value=true;message.value='播放源加载失败'}});hls.loadSource(url);hls.attachMedia(video.value)}else video.value.src=url;timer=setInterval(save,10000)}
async function share(){try{if(navigator.share)await navigator.share({title:vod.value?.vod_name||document.title,url:location.href});else{await navigator.clipboard.writeText(location.href);alert('链接已复制')}}catch{}}
async function load(){const id=route.params.id;if(!id)return;destroy();vod.value=null;recommend.value=[];resumeText.value='';playerLoading.value=true;try{const r=await getDetail(id);vod.value=r.data.list?.[0]||null;if(!vod.value){playerLoading.value=false;message.value='未找到该视频';return}history(vod.value);const url=vod.value.vod_play_url?.split('#')?.[0]?.split('$')?.[1];init(url);if(vod.value.type_id){const rec=await getCategoryLatest(vod.value.type_id,20);recommend.value=(rec.data.list||[]).filter(x=>String(x.vod_id)!==String(vod.value.vod_id)).slice(0,20)}document.title=vod.value.vod_name+' - CAVXX'}catch(e){console.error(e);playerLoading.value=true;message.value='视频加载失败，请刷新重试'}}
watch(()=>route.params.id,load,{immediate:true})
onBeforeUnmount(destroy)
</script>
<style scoped>
.play-page{padding:24px 0 56px}.play-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:18px;align-items:start}.player-column{min-width:0}.player-card,.video-info-card,.side-card{border:1px solid #ffffff13;background:linear-gradient(145deg,#ffffff0b,#ffffff05);box-shadow:0 14px 40px #0004}.player-card{overflow:hidden;border-radius:18px}.player-topbar{height:42px;display:flex;align-items:center;justify-content:space-between;padding:0 15px;border-bottom:1px solid #ffffff0f;color:#aaa;font-size:11px}.player-status span{display:inline-block;width:6px;height:6px;margin-right:7px;border-radius:50%;background:#f5c400}.player-wrap{position:relative;background:#050508}.player{display:block;width:100%;aspect-ratio:16/9;min-height:300px;background:#050508}.player-loading{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;color:#777;background:#050508;pointer-events:none}.player-loading i{font-size:42px;color:#ffdc36}.video-info-card{margin-top:14px;padding:22px 24px;border-radius:16px}.info-header{display:flex;justify-content:space-between;gap:18px}.eyebrow,.side-kicker{margin-bottom:8px;color:#ffd633;font-size:10px;font-weight:800;letter-spacing:.16em}.video-title{margin:0;color:#ffdc36;font-size:clamp(20px,2.2vw,29px)}.share-btn{height:38px;padding:0 14px;border:1px solid #ffffff17;border-radius:10px;background:#ffffff08;color:#ccc}.video-meta{display:flex;flex-wrap:wrap;gap:9px;margin-top:13px}.video-meta span{padding:6px 9px;border:1px solid #ffffff10;border-radius:7px;color:#888;font-size:11px}.description{margin-top:18px;padding-top:16px;border-top:1px solid #ffffff0f;color:#aaa}.description-text{margin-top:7px;color:#777;font-size:12px;line-height:1.8;white-space:pre-wrap}.side-card{padding:17px;border-radius:16px}.side-heading h2{font-size:18px;color:#eee}.side-list{display:flex;flex-direction:column;gap:10px}.side-item{display:flex;gap:10px;padding:7px;color:inherit;text-decoration:none}.side-item img{flex:0 0 108px;width:108px;height:66px;object-fit:cover;border-radius:8px}.side-item strong{display:block;color:#ffdc36;font-size:12px}.side-item small,.side-empty{color:#777;font-size:10px}.recommend-section{margin-top:30px}.section-bar{margin:20px 0 15px}.section-heading{margin:0;color:#eee;font-size:20px}.video-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:22px 16px}@media(max-width:1100px){.play-layout{grid-template-columns:minmax(0,1fr) 280px}.video-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:820px){.play-layout{display:block}.side-panel{display:none}.player{min-height:0}.video-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:640px){.play-page{padding:10px 0 32px}.page-shell{width:calc(100% - 20px)}.player-card{margin:0 -10px;border-radius:0}.video-info-card{padding:16px 14px}.video-title{font-size:19px}.video-grid{grid-template-columns:1fr}}
</style>
